 if TARGET_SIZE>SOURCE_SIZE:x+=APPEND
 elif TARGET_SIZE<SOURCE_SIZE:del x[TARGET_SIZE:]
 y=bytes(x)
 if len(y)!=TARGET_SIZE or sha(y)!=TARGET_SHA: raise ValueError(f'target mismatch {len(y)} {sha(y)}')
 return y
